{
  "restated_question": "Does the National Water Model (NWM) capture the daily hydropeaking surges observed at USGS Northport (02465000) on the Black Warrior River? If so, with what timing lag and magnitude accuracy relative to USGS 15-min peak and hourly-mean flows, and what explains any systematic discrepancies?",
  "hypotheses": [
    {
      "id": "H1",
      "claim": "The NWM fails to capture the hydropeaking pulse on days when its analysis/assimilation cycle does not include the pulse hour (Oct 18–22), showing near-baseflow values instead; on days when the cycle includes the pulse window (Oct 23–24), the NWM peaks 1 hour later than the USGS 15-min peak and underestimates the peak magnitude by ~200–500 cfs."
    },
    {
      "id": "H2",
      "claim": "The daily hydropeaking pulse at USGS Northport recurs at a consistent local hour (21:00 CDT on Oct 18–22, shifting to 19:00 CDT on Oct 23–24) with zero rainfall, confirming it is driven by scheduled hydropower releases at Holt Dam; the NWM lacks explicit dam-operation forcing, so it can only reproduce the pulse when its assimilation window happens to capture the observed surge."
    },
    {
      "id": "H3",
      "claim": "The NWS Oliver flow (TODA1) is derived from the same tailwater stage sensor as USGS 02465005 (verified by identical stage values), but the two agencies apply different stage-to-flow ratings, producing a systematic ~300–400 cfs daily-mean difference; this rating difference is unrelated to the NWM's ability to capture pulses but explains why NWS Oliver flows are consistently higher than USGS Northport daily means."
    }
  ],
  "checks": [
    {
      "id": "C1",
      "hypothesis": "H1",
      "purpose": "Quantify NWM performance on the two days it has data (Oct 23–24 CDT) by comparing the NWM peak flow, its timing lag relative to the USGS 15-min peak, and the magnitude error at the USGS peak hour and at the NWM peak hour.",
      "how": "SELECT local_day, usgs_peak_cfs, usgs_peak_hour_cdt, nwm_at_usgs_peak_cfs, nwm_peak_cfs, nwm_peak_hour_cdt, (nwm_peak_hour_cdt - usgs_peak_hour_cdt) AS lag_hours, (nwm_peak_cfs - usgs_peak_cfs) AS peak_error_cfs FROM (SELECT to_date(from_utc_timestamp(to_timestamp(hr_utc, 'yyyy-MM-dd HH:mm'), 'America/Chicago')) AS local_day, hour(from_utc_timestamp(to_timestamp(hr_utc, 'yyyy-MM-dd HH:mm'), 'America/Chicago')) AS hr_cdt, usgs_northport_peak_cfs, nwm_cfs FROM water.hourly_compare WHERE hr_utc >= '2026-10-23 05:00' AND hr_utc < '2026-10-25 05:00' AND usgs_northport_peak_cfs IS NOT NULL) t GROUP BY local_day HAVING MAX(usgs_northport_peak_cfs) > 1000"
    },
    {
      "id": "C2",
      "hypothesis": "H2",
      "purpose": "Verify the recurrence of the USGS Northport hydropeaking pulse at a consistent local hour across all 7 days (Oct 18–24) by extracting the CDT hour of the daily maximum 15-min peak; a fixed or predictably shifting hour confirms scheduled hydropower releases.",
      "how": "SELECT local_day, peak_hour_cdt, MAX(usgs_northport_peak_cfs) AS max_peak_cfs FROM (SELECT to_date(from_utc_timestamp(to_timestamp(hr_utc, 'yyyy-MM-dd HH:mm'), 'America/Chicago')) AS local_day, hour(from_utc_timestamp(to_timestamp(hr_utc, 'yyyy-MM-dd HH:mm'), 'America/Chicago')) AS peak_hour_cdt, usgs_northport_peak_cfs FROM water.hourly_compare WHERE hr_utc >= '2026-10-18 06:00' AND hr_utc < '2026-10-25 06:00' AND usgs_northport_peak_cfs IS NOT NULL) t GROUP BY local_day, peak_hour_cdt ORDER BY local_day, max_peak_cfs DESC"
    },
    {
      "id": "C3",
      "hypothesis": "H3",
      "purpose": "Confirm that USGS Oliver tailwater stage (02465005) and NWS Oliver tailwater stage (TODA1) are identical hour-by-hour (same physical sensor), while their derived flows differ, proving the ~300–400 cfs daily-mean gap is a rating-curve difference, not a stage measurement difference.",
      "how": "SELECT hr_utc, usgs_oliver_tailwater_ft, nws_oliver_tailwater_ft, nws_oliver_cfs, usgs_northport_cfs FROM water.hourly_compare WHERE hr_utc BETWEEN '2026-10-18 06:00' AND '2026-10-25 06:00' AND usgs_oliver_tailwater_ft IS NOT NULL AND nws_oliver_tailwater_ft IS NOT NULL ORDER BY hr_utc LIMIT 200"
    }
  ]
}
